import time
import random
import sys

def construct():
    start_time = time.time()
    deadline = start_time + 85.0  # Safety margin for 90s limit
    
    # Helper to check validity of adding x to a state defined by reachable_sums and global_map
    # Returns True if x can be added without violating constraints.
    def can_add(x, reachable_sums, global_map, current_size):
        # x must be distinct (handled by caller via set check)
        # Check collisions for new sums generated by adding x
        # new_sums[c] = {s + x for s in reachable_sums[c-1]}
        # If new_s is in global_map with cardinality != c, it's a conflict.
        
        for c in range(1, current_size + 2):
            if not reachable_sums[c-1]:
                continue
            for s in reachable_sums[c-1]:
                new_s = s + x
                if new_s in global_map:
                    if global_map[new_s] != c:
                        return False
        return True

    def add_element(x, reachable_sums, global_map, current_set):
        # Updates reachable_sums and global_map in place (or returns new ones)
        # For efficiency in local search, we might want to copy or use a stack.
        # Given small sizes, copying is acceptable.
        new_reachable = [set(s) for s in reachable_sums]
        current_size = len(current_set)
        
        # Update global_map and reachable_sums
        # Note: global_map is a dict. We need to update it.
        # Since we are doing local search, we need to be able to undo.
        # Strategy: Pass copies or record changes.
        # For simplicity in this implementation, we will pass copies of the state 
        # to the search functions, or use a class. 
        # Given Python overhead, passing copies of small sets/dicts is fine for k < 20.
        
        for c in range(1, current_size + 1):
            for s in reachable_sums[c-1]:
                new_s = s + x
                new_reachable[c].add(new_s)
                if new_s not in global_map:
                    global_map[new_s] = c
                # If it exists, it must be c (checked by can_add)
        
        current_set.append(x)
        return new_reachable, global_map, current_set

    def remove_element(x, reachable_sums, global_map, current_set):
        # This is harder. Removing an element requires recalculating sums.
        # It is much more efficient to represent the state as the set of elements 
        # and recompute reachable_sums from scratch for small k, 
        # OR maintain a structure that allows removal.
        
        # Given the complexity of dynamic removal from subset sum DP, 
        # and k being small (< 20), we can recompute reachable_sums 
        # from the current_set after modification.
        
        pass # Not used directly in this simplified ILS, see below.

    # To make local search efficient, we will maintain the set of elements.
    # Validity check requires reachable_sums.
    # We can recompute reachable_sums from the set of elements in O(k * 2^k) or similar?
    # No, DP is O(k * sum_range). Sum range is max 256*20 = 5120.
    # Recomputing DP for a set of size k takes O(k * 5120).
    # If k ~ 15, that's ~75k ops. Very fast.
    # So, we can afford to recompute the DP state from scratch after any modification (add/remove/swap).
    
    def compute_dp(elements):
        """
        Computes reachable_sums and global_map for a given list of elements.
        Returns (reachable_sums, global_map) or None if invalid.
        """
        n = len(elements)
        max_sum = sum(elements)
        # We don't need max_sum for the DP table size if we use sets, 
        # but sets are fine.
        
        reachable_sums = [set() for _ in range(n + 1)]
        reachable_sums[0].add(0)
        global_map = {0: 0}
        
        for x in elements:
            # Iterate backwards to avoid using the same element twice
            # But here we are adding to the set, so we update based on previous state.
            # Wait, the standard 0/1 knapsack DP update:
            # new_reachable[c] = old_reachable[c] U {s+x for s in old_reachable[c-1]}
            
            new_reachable = [set(s) for s in reachable_sums]
            for c in range(1, n + 1):
                # Only if c <= current index + 1
                if c <= elements.index(x) + 1: # This index check is fragile if duplicates, but elements are distinct.
                    # Better: just iterate c from 1 to current_count
                    pass
            
            # Let's do it cleanly:
            # We process elements one by one.
            # State: reachable_sums for the first i elements.
            # When adding element x (the i-th one, 1-indexed):
            for c in range(1, len(elements) + 1):
                if c > i: break # i is current count being built? No, i is loop var.
                
            # Let's restructure:
            current_count = 0
            for x in elements:
                current_count += 1
                new_reachable = [set(s) for s in reachable_sums]
                for c in range(1, current_count + 1):
                    for s in reachable_sums[c-1]:
                        new_s = s + x
                        new_reachable[c].add(new_s)
                        # Check conflict
                        if new_s in global_map:
                            if global_map[new_s] != c:
                                return None, None
                        else:
                            global_map[new_s] = c
                reachable_sums = new_reachable
                
        return reachable_sums, global_map

    # Optimization: compute_dp is O(k^2 * avg_set_size).
    # For k=15, this is very fast.
    
    def is_valid_set(elements):
        _, _ = compute_dp(elements)
        # compute_dp returns None if invalid
        # We need to distinguish "valid" from "invalid".
        # Let's make compute_dp return a boolean flag or handle None.
        # The above returns (None, None) on invalid.
        # So if reachable is not None, it's valid.
        pass

    def validate(elements):
        """Returns True if elements form a valid set."""
        n = len(elements)
        reachable_sums = [set() for _ in range(n + 1)]
        reachable_sums[0].add(0)
        global_map = {0: 0}
        
        current_count = 0
        for x in elements:
            current_count += 1
            new_reachable = [set(s) for s in reachable_sums]
            for c in range(1, current_count + 1):
                for s in reachable_sums[c-1]:
                    new_s = s + x
                    new_reachable[c].add(new_s)
                    if new_s in global_map:
                        if global_map[new_s] != c:
                            return False
                    else:
                        global_map[new_s] = c
            reachable_sums = new_reachable
        return True

    # ILS Strategy:
    # 1. Randomized Greedy Construction:
    #    - Start with empty set.
    #    - While we can add an element:
    #       - Pick a random candidate x from 1..256 not in set.
    #       - Check if adding x is valid (using incremental DP check or full validation).
    #       - To speed up, we can maintain the DP state incrementally.
    
    def incremental_greedy_random():
        """
        Builds a set using random greedy.
        Returns the list of elements.
        """
        reachable_sums = [set() for _ in range(20)]
        reachable_sums[0].add(0)
        global_map = {0: 0}
        current_set = []
        available = set(range(1, 257))
        
        while True:
            if time.time() > deadline:
                break
                
            # Shuffle available to pick random valid one
            # To avoid O(N) scan every time, we can just pick a random one and check.
            # If it fails, remove it from available? No, it might be valid later?
            # No, if it's invalid now, adding other elements makes the set "larger", 
            # which can only create MORE collisions, not fewer.
            # Wait, is that true?
            # If x is invalid because x collides with sum S of cardinality c, 
            # adding more elements doesn't remove S. So x remains invalid.
            # Therefore, we can maintain a list of "currently valid" candidates.
            
            if not available:
                break
                
            # Pick a random candidate from available
            x = random.choice(list(available))
            
            # Check validity
            valid = True
            for c in range(1, len(current_set) + 2):
                if not reachable_sums[c-1]:
                    continue
                for s in reachable_sums[c-1]:
                    new_s = s + x
                    if new_s in global_map:
                        if global_map[new_s] != c:
                            valid = False
                            break
                if not valid:
                    break
            
            if valid:
                # Commit x
                current_set.append(x)
                available.discard(x)
                
                # Update DP
                new_reachable = [set(s) for s in reachable_sums]
                for c in range(1, len(current_set) + 1):
                    for s in reachable_sums[c-1]:
                        new_s = s + x
                        new_reachable[c].add(new_s)
                        if new_s not in global_map:
                            global_map[new_s] = c
                        # If in map, it's c
                reachable_sums = new_reachable
            else:
                # x is invalid, remove from available
                available.discard(x)
                
        return current_set

    def local_search_improve(initial_set):
        """
        Attempts to improve the set size by swapping elements.
        Returns the best set found.
        """
        current_best = list(initial_set)
        best_size = len(current_best)
        
        # Precompute validation for current state?
        # We will use validate() which is O(k^2).
        
        improved = True
        while improved and time.time() < deadline:
            improved = False
            # Try to add an element
            for x in range(1, 257):
                if x in current_best:
                    continue
                new_set = current_best + [x]
                if validate(new_set):
                    current_best = new_set
                    best_size += 1
                    improved = True
                    break # Restart loop with new size
            
            if improved:
                continue
                
            # Try to swap: remove i, add j
            # To find a swap that increases size, we usually try to remove one and add two? 
            # No, size must increase. 
            # If we can't add, maybe we can swap a "bad" element for a "better" one 
            # that allows future additions?
            # Simple swap (remove 1, add 1) keeps size same. Doesn't help maximize size directly 
            # unless it unlocks additions.
            
            # Let's try 1-for-1 swaps to see if it unlocks an addition.
            # This is expensive. 
            # Alternative: Random restarts are often better for this small search space.
            
            # Let's just do random restarts in the main loop.
            break
            
        return current_best

    # Main ILS Loop
    best_set = []
    
    # First, try the deterministic greedy (smallest first) as a baseline
    # Re-implementing smallest-first greedy for comparison
    def greedy_smallest():
        reachable_sums = [set() for _ in range(20)]
        reachable_sums[0].add(0)
        global_map = {0: 0}
        current_set = []
        
        while True:
            if time.time() > deadline:
                break
            added = False
            for x in range(1, 257):
                if x in current_set:
                    continue
                valid = True
                for c in range(1, len(current_set) + 2):
                    if not reachable_sums[c-1]:
                        continue
                    for s in reachable_sums[c-1]:
                        new_s = s + x
                        if new_s in global_map:
                            if global_map[new_s] != c:
                                valid = False
                                break
                    if not valid:
                        break
                if valid:
                    current_set.append(x)
                    new_reachable = [set(s) for s in reachable_sums]
                    for c in range(1, len(current_set) + 1):
                        for s in reachable_sums[c-1]:
                            new_s = s + x
                            new_reachable[c].add(new_s)
                            if new_s not in global_map:
                                global_map[new_s] = c
                    reachable_sums = new_reachable
                    added = True
                    break
            if not added:
                break
        return current_set

    # Run baseline
    baseline = greedy_smallest()
    if len(baseline) > len(best_set):
        best_set = baseline

    # Run ILS
    restarts = 0
    while time.time() < deadline:
        restarts += 1
        # Random seed for reproducibility in debugging, but random for exploration
        # We don't need to set seed if we want diversity.
        
        candidate = incremental_greedy_random()
        
        # Try to improve candidate with simple local search (add if possible)
        # The greedy already adds as much as it can randomly.
        # Maybe try to add in smallest order after random construction?
        # Let's try a "completion" phase: try to add smallest valid numbers to the random set.
        
        # Rebuild DP for candidate to do completion
        # Actually, incremental_greedy_random already maximized size for that random path.
        # But maybe a different order of additions would have allowed more?
        # The "completion" phase tries to add any valid number, smallest first.
        
        # Let's implement a function to "complete" a set by trying to add any valid number.
        def complete_set(elements):
            # Validate first
            if not validate(elements):
                return elements
            
            # Rebuild DP state
            n = len(elements)
            reachable_sums = [set() for _ in range(n + 10)]
            reachable_sums[0].add(0)
            global_map = {0: 0}
            
            # Build DP from scratch for this set
            current_count = 0
            for x in elements:
                current_count += 1
                new_reachable = [set(s) for s in reachable_sums]
                for c in range(1, current_count + 1):
                    for s in reachable_sums[c-1]:
                        new_s = s + x
                        new_reachable[c].add(new_s)
                        if new_s not in global_map:
                            global_map[new_s] = c
                        # else it must be c
                reachable_sums = new_reachable
            
            # Now try to add more
            while True:
                if time.time() > deadline:
                    break
                added = False
                for x in range(1, 257):
                    if x in elements:
                        continue
                    valid = True
                    for c in range(1, len(elements) + 2):
                        if not reachable_sums[c-1]:
                            continue
                        for s in reachable_sums[c-1]:
                            new_s = s + x
                            if new_s in global_map:
                                if global_map[new_s] != c:
                                    valid = False
                                    break
                        if not valid:
                            break
                    if valid:
                        elements.append(x)
                        new_reachable = [set(s) for s in reachable_sums]
                        for c in range(1, len(elements) + 1):
                            for s in reachable_sums[c-1]:
                                new_s = s + x
                                new_reachable[c].add(new_s)
                                if new_s not in global_map:
                                    global_map[new_s] = c
                        reachable_sums = new_reachable
                        added = True
                        break
                if not added:
                    break
            return elements

        completed = complete_set(candidate)
        
        if len(completed) > len(best_set):
            best_set = completed
            # If we reached a high size, maybe stop early?
            # Max possible size is bounded. 1..256.
            # If best_size > 15, it's good.
            
    # Final check: ensure best_set is valid
    if not validate(best_set):
        # Fallback to baseline if something went wrong
        if validate(baseline):
            best_set = baseline
        else:
            # Return empty or minimal valid set
            best_set = [1]

    # Convert to list of ints
    return [int(x) for x in best_set]

